// InterviewTracker.java - Track and analyze your interviews
public record InterviewRecord(
    String company,
    LocalDate date,
    List<String> technicalQuestions,
    List<String> strengthAreas,
    List<String> improvementAreas,
    String interviewerEmail,
    boolean thankYouSent
) {
    public static InterviewRecord create(String company, String email) {
        return new InterviewRecord(
            company,
            LocalDate.now(),
            new ArrayList<>(),
            new ArrayList<>(),
            new ArrayList<>(),
            email,
            false
        );
    }

    // Add questions immediately after interview while memory is fresh
    public InterviewRecord addQuestion(String question) {
        technicalQuestions.add(question);
        return this;
    }
}

// RejectionAnalyzer.java - Learn from patterns in rejections
public class RejectionAnalyzer {
    record Rejection(
        String company,
        String stage,  // screening, technical, final
        String reason, // from feedback if available
        LocalDate date
    ) {}

    private final List<Rejection> rejections = new ArrayList<>();

    public void recordRejection(String company, String stage, String reason) {
        rejections.add(new Rejection(company, stage, reason, LocalDate.now()));
        analyzePatterns();
    }

    private void analyzePatterns() {
        // Group by stage to find where you're stuck
        var byStage = rejections.stream()
            .collect(Collectors.groupingBy(Rejection::stage, Collectors.counting()));

        // If most rejections are at technical round, focus on DSA and system design
        System.out.println("Rejection breakdown: " + byStage);
    }
}

// FirstWeekChecklist.java - Track your onboarding progress
public class FirstWeekChecklist {
    record Task(String name, boolean completed, String notes) {}

    private final List<Task> tasks = List.of(
        new Task("Clone main repositories", false, ""),
        new Task("Run application locally", false, ""),
        new Task("Read architecture documentation", false, ""),
        new Task("Review past 10 pull requests", false, ""),
        new Task("Set up IDE with team conventions", false, ""),
        new Task("Understand deployment process", false, ""),
        new Task("Map out service dependencies", false, ""),
        new Task("Schedule 1-on-1 with each team member", false, ""),
        new Task("Document questions for manager", false, "")
    );

    // Track what you learn each day
    public void logLearning(String task, String notes) {
        System.out.println("Learned: " + task + " - " + notes);
    }
}
